            h2o_configurator_errprintf(cmd, *br_node,
                                       "value of br attribute must be either of `OFF`, `ON` or an integer between 0 and 11");
            return -1;
        }
    } break;
    default:
        h2o_fatal("unexpected node type");
        break;
    }

    return 0;
}


